-- PartyBroc : Quiz culture G (questions). Relançable.
-- À lancer dans la base party, avec le rôle partybroc :
--
--   psql -h localhost -U partybroc -d party -f 02_quiz.sql
--
-- Pour ajouter des questions : ajoute des lignes dans le VALUES et relance.
-- Une question déjà présente (même texte) est mise à jour, pas dupliquée.
-- Pour en retirer une sans la supprimer : update pb_quiz_questions set active = false where ...

\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
BEGIN;
SET search_path = pb;

CREATE TABLE IF NOT EXISTS pb_quiz_questions (
  id         integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  category   text     NOT NULL,
  difficulty smallint NOT NULL DEFAULT 1 CHECK (difficulty BETWEEN 1 AND 3),
  question   text     NOT NULL UNIQUE,
  good       text     NOT NULL,                  -- la bonne réponse
  bad        text[]   NOT NULL CHECK (cardinality(bad) = 3),  -- les 3 mauvaises
  active     boolean  NOT NULL DEFAULT true
);

ON CONFLICT (question) DO UPDATE
  SET category = excluded.category, difficulty = excluded.difficulty,
      good = excluded.good, bad = excluded.bad;

COMMIT;

SELECT category, count(*) AS questions FROM pb_quiz_questions WHERE active GROUP BY category ORDER BY category;
